<script>const radios=document.querySelectorAll('input[name="address_id"]');const fields=document.getElementById('new-address-fields');function updateAddressForm(){const isNew=document.querySelector('input[name="address_id"]:checked')?.value==="";fields.classList.toggle('active',isNew);fields.querySelectorAll('input:not([type="hidden"]),textarea,select').forEach(el=>{el.required=isNew;el.disabled=!isNew})}radios.forEach(r=>r.addEventListener('change',updateAddressForm));updateAddressForm();document.getElementById('locate').addEventListener('click',()=>{const s=document.getElementById('location-status');if(!navigator.geolocation){s.textContent='Location is not supported by this browser.';return}s.textContent='Getting your location…';navigator.geolocation.getCurrentPosition(p=>{document.getElementById('latitude').value=p.coords.latitude.toFixed(7);document.getElementById('longitude').value=p.coords.longitude.toFixed(7);s.textContent='Location captured. You can adjust the pin on the map.';if(window.addressMarker){const pos={lat:p.coords.latitude,lng:p.coords.longitude};window.addressMarker.setPosition(pos);window.addressMap.setCenter(pos);window.addressMap.setZoom(16)}},e=>s.textContent='Could not get location: '+e.message,{enableHighAccuracy:true,timeout:10000})});</script>
@if(config('services.google_maps.key'))<script>function initAddressMap(){const lat=parseFloat(document.getElementById('latitude').value)||22.9734,lng=parseFloat(document.getElementById('longitude').value)||78.6569;const map=new google.maps.Map(document.getElementById('address-map'),{center:{lat,lng},zoom:5});const marker=new google.maps.Marker({position:{lat,lng},map,draggable:true});window.addressMap=map;window.addressMarker=marker;function save(p){document.getElementById('latitude').value=p.lat().toFixed(7);document.getElementById('longitude').value=p.lng().toFixed(7);document.getElementById('location-status').textContent='Map pin saved.'}marker.addListener('dragend',()=>save(marker.getPosition()));map.addListener('click',e=>{marker.setPosition(e.latLng);save(e.latLng)})}</script><script src="https://maps.googleapis.com/maps/api/js?key={{ config('services.google_maps.key') }}&callback=initAddressMap" async defer></script>@endif
